(* [comment removed for export] *)
Definition pf_ctx (m m1 : mem) (sp : word) (SV : list cell) (B E L lo shi : Z) (p0 : Z) (bs : list byte)
    (lowc tmp : list cell) (pv : Z) (nmc vlc : list cell) (bsz : Z) (bb : list byte) (ecs : list cell) (g : bool) : Prop :=
  rw_cells asegs m1 (bv_unsigned sp + -176) lowc
  /\ rw_cells asegs m1 (bv_unsigned sp + -128) tmp
  /\ rw_cells asegs m1 (bv_unsigned sp + -104) SV
  /\ rw_cells asegs m1 (bv_unsigned sp + 176) [C8 (wz pv)]
  /\ rw_cells asegs m1 (bv_unsigned sp + 200) nmc
  /\ rw_cells asegs m1 (bv_unsigned sp + 184) vlc
  /\ rw_cells asegs m1 B [C8 (wz bsz); CB 4096 bb]
  /\ rw_cells asegs m1 E ecs
  /\ bytes_at asegs m1 p0 bs /\ L = p0 + Z.of_nat (length bs) /\ APfTab m1
  /\ AHttpCat m1 g
  /\ stk asegs m1 lo (bv_unsigned sp + -176)
  /\ munch (pf_W lo sp B E) m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
  /\ pf_side m B E p0 (Z.of_nat (length bs)) lo shi.

(* [comment removed for export] *)
Definition pf_lows (x0 x8 x16 : word) (E : Z) (x40 : word) : list cell :=
  [C8 x0; C8 x8; C8 x16; C8 (wz (E + 16)); C8 (shw (E + 16)); C8 x40].

Lemma pf_pwin : forall sp B E lo shi p0 bs E0, pf_pure sp B E lo shi p0 bs E0 -> Forall pwin (pf_W lo sp B E).
Proof.
  intros sp B E lo shi p0 bs E0 (_ & _ & LO & CEIL & APW & APE & EAL & APB & BAL & _).
  unfold pf_W, PF_STACK, AASSIGN_STACK, AINTRIN_STACK in *. repeat apply Forall_cons; [| | | | | apply Forall_nil].
  - apply pwin_stack. exact CEIL.
  - apply pwin_stack. clear - CEIL LO. lia.
  - eapply pwin_aapp; [exact APB| clear; lia| clear; lia].
  - eapply pwin_aapp; [exact APE| clear; lia| clear; lia].
  - exact pwin_httpcat.
Qed.
