(* [comment removed for export] *)
Lemma pf_far_transport : forall m1 m2 (sp : word) lo B E p0 (bs : list byte) pv (nmc vlc : list cell) bsz bb,
  munch [(lo, bv_unsigned sp); (E, E + 24); (AG_HTTP_CAT, AG_HTTP_CAT + 64)]%Z m1 m2 -> wmono asegs m1 m2 ->
  aceil <= lo -> lo <= bv_unsigned sp -> aapp B 4104 -> aapp p0 (Z.of_nat (length bs)) -> aapp E 24 ->
  (B + 4104 <= E \/ E + 24 <= B) -> (p0 + Z.of_nat (length bs) <= E \/ E + 24 <= p0) ->
  cells_size nmc = 16%nat -> cells_size vlc = 16%nat ->
  rw_cells asegs m1 (bv_unsigned sp + 176) [C8 (wz pv)] -> rw_cells asegs m1 (bv_unsigned sp + 200) nmc ->
  rw_cells asegs m1 (bv_unsigned sp + 184) vlc -> rw_cells asegs m1 B [C8 (wz bsz); CB 4096 bb] ->
  bytes_at asegs m1 p0 bs -> APfTab m1 ->
  rw_cells asegs m2 (bv_unsigned sp + 176) [C8 (wz pv)] /\ rw_cells asegs m2 (bv_unsigned sp + 200) nmc
  /\ rw_cells asegs m2 (bv_unsigned sp + 184) vlc /\ rw_cells asegs m2 B [C8 (wz bsz); CB 4096 bb]
