(* [comment removed for export] *)
Definition pf_exitA_stmt (k : nat) (pc e loc : Z) : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s4x s5x s6x s7x s8x s10x s11x
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (B E L lo shi : Z) (p0 : Z) (bs : list byte) (E0 : ecv)
    (lowc : list cell) (pv : Z) (nmc vlc : list cell) (bsz : Z) (bb : list byte) (e1 e2 e3 : word) (g : bool) (j24 : list byte),
  pf_ctx m m1 sp (pch_saved s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) B E L lo shi p0 bs
         lowc [CB 24 j24] pv nmc vlc bsz bb [C8 e1; C8 e2; C8 e3] g ->
  pf_pure sp B E lo shi p0 bs E0 -> 0 <= bsz <= 4096 -> 0 <= pv < 2^64 ->
  cells_size lowc = 48%nat -> cells_size nmc = 16%nat -> cells_size vlc = 16%nat ->
  In e [HE_NEED_MORE; HE_HEADER_LIMIT; HE_BAD_LINE_ENDING; HE_BAD_FIELD; HE_BAD_VALUE] ->
  evt asegs (pf_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc B E lo shi p0 bs E0 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -176)) gp tp t0 t1 t2 (wz E) s1x a0 a1 a2 a3 a4 a5 a6 a7
              s2x (pick k 1 (wz (E + 16)) s3x) s4x s5x s6x s7x (pick k 1 (shw (E + 16)) s8x) (wz 2147450880) s10x s11x t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom asegs)).

(* [comment removed for export] *)
Definition pf_exitS_stmt (k : nat) (pc e loc : Z) : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s4x s5x s6x s7x s8x s10x s11x
         s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (B E L lo shi : Z) (p0 : Z) (bs : list byte) (E0 : ecv)
    (x0 x8 x16 x40 : word) (pv : Z) (nmc vlc : list cell) (bsz : Z) (bb : list byte) (e1 e2 e3 : word) (g : bool) (j24 : list byte),
  pf_ctx m m1 sp (pch_saved s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) B E L lo shi p0 bs
         (pf_lows x0 x8 x16 E x40) [CB 24 j24] pv nmc vlc bsz bb [C8 e1; C8 e2; C8 e3] g ->
  pf_pure sp B E lo shi p0 bs E0 -> 0 <= bsz <= 4096 -> 0 <= pv < 2^64 ->
  cells_size nmc = 16%nat -> cells_size vlc = 16%nat ->
